<script setup lang="ts">
import { computed, ref, useId, watch } from 'vue'
import { Copy, Check } from 'lucide-vue-next'
import { copyText } from '@/utils/copyText'
import type { OrderProgress } from '@/api/order-progress'
import { documentNames, progressLayout, progressStatus } from '@/utils/order-progress-graph'
const props=withDefaults(defineProps<{source:OrderProgress['graph'];title?:string}>(),{title:'单据关系'})
const arrowId=useId(),selected=ref(''),copied=ref(''),copyMessage=ref('')
const graph=computed(()=>props.source?progressLayout(props.source):null)
const active=computed(()=>graph.value?.nodes.find(n=>n.id===selected.value))
watch(()=>props.source,source=>{selected.value=source?.rootDocumentId??'';copied.value='';copyMessage.value=''},{immediate:true})
async function copyNumber(value:string|null){if(!value)return;try{await copyText(value);copied.value=value;copyMessage.value='单据编号已复制'}catch{copyMessage.value='复制失败，请选中单号手动复制'}}
</script>
<template>
   <div class="panel-section"><div class="graph-heading"><h3>{{title}}</h3><span v-if="graph">{{graph.nodes.length}} 张单据</span></div>
    <slot /><div v-if="graph" class="graph-scroll"><div class="graph-canvas" :style="{width:graph.width+'px',height:graph.height+'px'}"><svg :width="graph.width" :height="graph.height" aria-hidden="true"><defs><marker :id="arrowId" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" /></marker></defs><path v-for="e in graph.edges" :key="e.id" class="edge" :d="e.path" :marker-end="`url(#${arrowId})`" /></svg><div v-for="node in graph.nodes" role="button" tabindex="0" @keydown.enter.self="selected=node.id" @keydown.space.prevent.self="selected=node.id" :key="node.id" class="document" :class="{selected:selected===node.id}" :style="{left:node.x+'px',top:node.y+'px'}" @click="selected=node.id"><small>{{documentNames[node.entity]||'业务单据'}}</small><div class="node-number"><strong>{{node.number||'—'}}</strong><button v-if="node.number" type="button" class="copy-number" :aria-label="`复制单据编号 ${node.number}`" @click.stop="copyNumber(node.number)"><Check v-if="copied===node.number" :size="13"/><Copy v-else :size="13"/></button></div><span v-if="node.billStatus" class="state">{{progressStatus(node.billStatus)}}</span><span v-if="node.businessStatus" class="state business-state">{{node.businessStatus}}</span></div></div></div>
    <p v-else class="message">暂无可展示的单据关系</p>
    <p v-if="copyMessage" role="status" class="copy-feedback">{{copyMessage}}</p><div v-if="active" class="document-detail"><span>{{documentNames[active.entity]||'业务单据'}}</span><strong>{{active.number}}</strong><span>{{active.businessStatus || progressStatus(active.billStatus)}}</span></div>
   </div>
</template>
<style scoped>
h3{font-size:14px;font-weight:600}.summary>.state{flex-shrink:0;align-self:flex-start}.node-number{display:flex;align-items:center;gap:6px}.node-number strong{min-width:0}.copy-number{color:var(--color-link);padding:4px;flex-shrink:0;border-radius:4px}.copy-number:hover{background:var(--color-selection-surface)}.copy-feedback{font-size:12px;color:var(--color-text-secondary);margin-top:10px}.document:focus-visible{outline:2px solid var(--color-link);outline-offset:2px}.summary h3{font-size:19px;margin:6px 0}.panel-section{background:var(--color-surface);border:1px solid var(--color-border);border-radius:10px;margin-top:16px;padding:20px}.graph-heading{display:flex;justify-content:space-between}.graph-heading span,.message,.empty{font-size:13px;color:var(--color-text-secondary)}.message{padding:15px 0}.graph-scroll{overflow:auto;margin-top:16px;background:var(--color-surface-muted);border-radius:8px}.graph-canvas{position:relative}.graph-canvas>svg{position:absolute;inset:0;pointer-events:none}.edge{fill:none;stroke:var(--color-link);stroke-width:1.5;opacity:.6}marker path{fill:var(--color-link)}.document{position:absolute;width:220px;min-height:104px;text-align:left;padding:14px;background:var(--color-surface);border:1px solid var(--color-border);border-radius:8px;box-shadow:0 3px 10px #00000008}.document.selected{border-color:var(--color-link);box-shadow:0 0 0 1px var(--color-link)}.document small{display:block;color:var(--color-text-secondary);font-size:12px}.document strong{display:block;font-size:13px;font-weight:600;color:var(--color-link);margin:8px 0;overflow-wrap:anywhere}.state{font-size:11px;background:var(--color-selection-surface);color:var(--color-selection-text);padding:3px 7px;border-radius:4px}.business-state{margin-left:5px}.document-detail{display:flex;flex-wrap:wrap;gap:16px;font-size:12px;border-top:1px solid var(--color-border);padding-top:16px;margin-top:16px}button:focus-visible,a:focus-visible{outline:2px solid var(--color-link);outline-offset:2px}
</style>
